@js:
var result = [];
var sessionId = '';

var loginInfo = source.getLoginInfoMap();
if (loginInfo && loginInfo['sessionid']) {
    sessionId = loginInfo['sessionid'];
}

if (!sessionId) {
    var cookies = cookie.getCookie('103.189.141.163');
    if (cookies) {
        var match = cookies.match(/sessionid=([^;]+)/);
        if (match && match[1]) {
            sessionId = match[1];
        }
    }
}

if (sessionId) {
    result.push({
        title: '📚 我的书架',
        url: 'http://103.189.141.163:9587/fq?action=shujia&sessionid=' + sessionId,
        style: {layout_flexGrow: 1, layout_flexBasisPercent: 1}
    });
} else {
    result.push({
        title: '请先登录',
        url: '',
        style: {layout_flexGrow: 1, layout_flexBasisPercent: 1}
    });
}

JSON.stringify(result);

